// Queued box entropy and sizes, DegenerusGameLootboxModule.resolveHumanBoxOrder (audit 4f4aa8377,
// LOOTBOX-COMPACT-ORDER-CLIENT-HANDOFF §2-§4). One 85-bit entry per order, three per word:
//   [0:32] wallet ID · [32:53] per-box units of LB_VALUE_UNIT · [53:65] activity-score code
//   [65:77] boon boost bps · [77:84] quantity 1-100 · [84] distress
// The entry holds no level, kind, cover flag, EV field or tier counts: every order is one lane of
// `quantity` boxes at units x LB_VALUE_UNIT, rolled at the live open level.
import { AbiCoder, keccak256 } from 'ethers';
import { boxQueuePosition } from '../chain/box-queue.js';
import { ETH_DIVISOR } from './chain-config.js';
import { hasCompactBoxQueue, hasOpeningLootboxEv } from '../chain/schema.js';
const coder = AbiCoder.defaultAbiCoder();
const hash4 = (...words) => BigInt(keccak256(coder.encode(['uint256','uint256','uint256','uint256'],words)));

/** LB_VALUE_UNIT in deployed wei: 0.001 ETH mainnet, 1e9 wei on the ÷1e6 testnet overlay. */
export const BOX_ENTRY_VALUE_UNIT_WEI = (10n ** 15n) / ETH_DIVISOR;
const SCORE_CODE_EXACT = 2042n, SCORE_CODE_STEP = 14n, SCORE_CAP = 30000n;

/** §4 `_scoreCode`: clamp to 30,000, exact through 2,042, then floor-step by 14 (cap = code 4,039). */
export function encodeBoxScoreCode(score) {
  let s = BigInt(score); if (s < 0n) throw new RangeError('Invalid activity score.');
  if (s > SCORE_CAP) s = SCORE_CAP;
  return s <= SCORE_CODE_EXACT ? s : SCORE_CODE_EXACT + (s - SCORE_CODE_EXACT) / SCORE_CODE_STEP;
}
/** §4 `_scoreFromCode`. */
export function decodeBoxScoreCode(code) {
  const c = BigInt(code);
  return c <= SCORE_CODE_EXACT ? c : SCORE_CODE_EXACT + (c - SCORE_CODE_EXACT) * SCORE_CODE_STEP;
}

/** Decode one stored 85-bit queue entry (§2). */
export function decodeBoxQueueEntry(packed) {
  const entry = BigInt(packed ?? 0);
  const units = (entry >> 32n) & 0x1fffffn;
  const quantity = Number((entry >> 77n) & 0x7fn);
  return {
    id: entry & 0xffffffffn,
    units,
    perBoxWei: units * BOX_ENTRY_VALUE_UNIT_WEI,
    scoreCode: (entry >> 53n) & 0xfffn,
    score: decodeBoxScoreCode((entry >> 53n) & 0xfffn),
    boostBps: (entry >> 65n) & 0xfffn,
    quantity,
    distress: ((entry >> 84n) & 1n) === 1n,
    nominalWei: BigInt(quantity) * units * BOX_ENTRY_VALUE_UNIT_WEI,
  };
}

// `priceForLevel` is kept in the signature for callers; the entry no longer stores a preset kind or
// level, so it is unused. `openingEvBps` is the order's EV allowance fraction (drawn once at the live
// opening level) — only bonus-scaled values need it.
export function queuedBoxRolls({ packedBox, rngWord, lootboxIndex, openingEvBps = null }, priceForLevel, evMultiplier) {
  if (!hasCompactBoxQueue()) return legacyQueuedBoxRolls({ packedBox, rngWord, lootboxIndex, openingEvBps }, priceForLevel, evMultiplier);
  const entry=BigInt(packedBox??0), word=BigInt(rngWord??0), position=boxQueuePosition(lootboxIndex??0);
  if (!entry || !word || !position) return null;
  const order=decodeBoxQueueEntry(entry), id=order.id;
  if (!id || !order.quantity || !order.units) return null;
  const adj = openingEvBps == null ? null : BigInt(openingEvBps);
  if (adj != null && (adj < 0n || adj > 10000n)) throw new RangeError('Invalid opening EV fraction.');
  const root=hash4(0x5175657565644f72646572n,word,position.buffer,position.position);
  const boonSeed=hash4(root,id,0x426f78426f6f6en,position.buffer);
  const score=order.score, ev=evMultiplier(score), amount=order.perBoxWei;
  const boosted=amount+amount*order.boostBps/10000n;
  const eligible=adj == null ? null : amount*adj/10000n;
  const scaled=ev<=10000n?boosted*ev/10000n:eligible == null ? null : eligible*ev/10000n+boosted-eligible;
  // Box n (1-based) seeds hash4(root, id, BOX_OPEN_TAG, n) and draws its boon at nonce n - 1.
  const rolls=[];
  for(let n=1n;n<=BigInt(order.quantity);n++) rolls.push({seed:hash4(root,id,0x426f784f70656en,n),scaled,nonce:n-1n});
  return {id,level:null,score,root,boonSeed,rolls,order};
}

// Runs 66-74 (audit 98cd2a781 to 4f4aa8377): one whole-word counted order per position — level
// [32:56], score [56:71], boost [71:85], EV [85:99], counts [100:128] (small/medium/large/custom),
// gwei custom size [128:184], cover flag 184. Kept verbatim for archived deployments.
function legacyQueuedBoxRolls({ packedBox, rngWord, lootboxIndex, openingEvBps = null }, priceForLevel, evMultiplier) {
  const entry=BigInt(packedBox??0), word=BigInt(rngWord??0), position=boxQueuePosition(lootboxIndex??0);
  if (!entry || !word || !position) return null;
  const id=entry&0xffffffffn;
  if (!id) return null;
  const level=Number((entry>>32n)&0xffffffn), score=(entry>>56n)&0x7fffn;
  const boost=(entry>>71n)&0x3fffn;
  const adj=hasOpeningLootboxEv()
    ? (openingEvBps == null ? null : BigInt(openingEvBps))
    : (entry>>85n)&0x3fffn;
  if (adj != null && (adj < 0n || adj > 10000n)) throw new RangeError('Invalid opening EV fraction.');
  const size=((entry>>128n)&0xffffffffffffffn)*1000000000n;
  const root=hash4(0x5175657565644f72646572n,word,position.buffer,position.position);
  const boonSeed=hash4(root,id,0x426f78426f6f6en,position.buffer);
  const price=priceForLevel(level), ev=evMultiplier(score);
  const counts=[100n,107n,114n,121n].map(shift=>Number((entry>>shift)&127n));
  const lanes=entry&(1n<<184n)?[[1,size]]:counts.map((n,i)=>[n,[price,price*5n,price*25n,size][i]]);
  let nonce=0n;const rolls=[];
  for(const [count,amount] of lanes) {
    const boosted=amount+amount*boost/10000n;
    const eligible=adj == null ? null : amount*adj/10000n;
    const scaled=ev<=10000n?boosted*ev/10000n:eligible == null ? null : eligible*ev/10000n+boosted-eligible;
    for(let i=0;i<count;i++) rolls.push({seed:hash4(root,id,0x426f784f70656en,++nonce),scaled,nonce:nonce-1n});
  }
  return {id,level,score,root,boonSeed,rolls};
}
